import pytest
from pricing import parse_price


@pytest.mark.parametrize("text, expected", [
    ("$5", 5.00),
    ("$5.50", 5.50),
    ("  $12.00 ", 12.00),
])
def test_parse_price_reads_dollar_amounts(text, expected):
    assert parse_price(text) == expected


def test_parse_price_rejects_text_without_an_amount():
    with pytest.raises(ValueError):
        parse_price("free")


