def price_file(tmp_path):
    path = tmp_path / "prices.txt"
    path.write_text("$1\n$2.50\n")
    return path


def test_prices_in_file_add_up(price_file):
    lines = price_file.read_text().splitlines()
    assert sum(parse_price(line) for line in lines) == 3.50

