// A tiny stand-in for Vitest so this runs in the browser.
// In a real project: import { it, expect } from 'vitest'
const results = []
function it(name, fn) {
  try {
    fn()
    results.push('PASS ' + name)
  } catch (error) {
    results.push('FAIL ' + name + ': ' + error.message)
  }
}
function expect(actual) {
  const show = (v) => JSON.stringify(v)
  return {
    toBe(expected) {
      if (!Object.is(actual, expected)) throw new Error(`expected ${show(expected)}, got ${show(actual)} (not the same object)`)
    },
    toEqual(expected) {
      if (show(actual) !== show(expected)) throw new Error(`expected ${show(expected)}, got ${show(actual)}`)
    },
    toThrow() {
      let threw = false
      try { actual() } catch { threw = true }
      if (!threw) throw new Error('expected the function to throw')
    }
  }
}

