def paginate(items, page, per_page):
    """Return the items on a page. Pages are numbered from 1."""
    start = page * per_page
    return items[start:start + per_page]


def test_first_page():
    assert paginate(["a", "b", "c", "d", "e"], 1, 2) == ["a", "b"]

def test_last_partial_page():
    assert paginate(["a", "b", "c", "d", "e"], 3, 2) == ["e"]

def test_page_past_the_end_is_empty():
    assert paginate(["a", "b", "c", "d", "e"], 4, 2) == []

def test_empty_list_has_empty_first_page():
    assert paginate([], 1, 10) == []


tests = [test_first_page, test_last_partial_page,
         test_page_past_the_end_is_empty, test_empty_list_has_empty_first_page]
passed = 0
for test in tests:
    try:
        test()
        passed += 1
    except AssertionError:
        print("FAIL", test.__name__)
print(f"{passed} of {len(tests)} tests passed")

