MIN_LENGTH = 8


def is_strong(password):
    return len(password) >= MIN_LENGTH and any(c.isdigit() for c in password)


def test_rejects_short_password():
    assert is_strong("abc1") is False


def test_rejects_password_without_digit():
    assert is_strong("abcdefgh") is False


def test_accepts_long_password_with_digit():
    assert is_strong("abcdefg1") is True

